import * as fs from 'fs';
import * as os from 'os';
import * as path from 'path';
import * as util from 'util';
import * as core from '@actions/core';
import * as httpm from '@actions/http-client';
import * as tc from '@actions/tool-cache';
import * as cache from '@actions/cache';
const osPlat = os.platform();
const osArch = os.arch();
export const getRelease = async (version) => {
    const url = `https://raw.githubusercontent.com/step-security/mage-action/release/.github/mage-releases.json`; // update ref to main branch post release
    const http = new httpm.HttpClient('ghaction-setup-containerd');
    const resp = await http.get(url);
    const body = await resp.readBody();
    const statusCode = resp.message.statusCode || 500;
    if (statusCode >= 400) {
        throw new Error(`Failed to get Mage release ${version} from ${url} with status code ${statusCode}: ${body}`);
    }
    const releases = JSON.parse(body);
    if (!releases[version]) {
        throw new Error(`Cannot find Mage release ${version} in ${url}`);
    }
    return releases[version];
};
export async function getMage(version, cacheBinary) {
    const release = await getRelease(version);
    const semver = release.tag_name.replace(/^v/, '');
    core.info(`Mage version found: ${release.tag_name}`);
    const filename = getFilename(semver);
    const magePath = tc.find('mage-action', semver);
    if (magePath) {
        core.info(`Mage binary found in local cache @ ${magePath}`);
        return getExePath(magePath);
    }
    const mageHome = path.join(`${process.env.HOME}`, '.mage');
    if (!fs.existsSync(mageHome)) {
        fs.mkdirSync(mageHome, { recursive: true });
    }
    if (cacheBinary && cache.isFeatureAvailable()) {
        core.debug(`GitHub actions cache feature available`);
        const cacheKey = await cache.restoreCache([getExePath(mageHome)], getCacheKey(semver));
        if (cacheKey) {
            core.info(`Restored ${cacheKey} from GitHub actions cache`);
            const cachePath = await tc.cacheDir(mageHome, 'mage-action', semver);
            return getExePath(cachePath);
        }
    }
    const downloadUrl = util.format('https://github.com/magefile/mage/releases/download/%s/%s', release.tag_name, filename);
    core.info(`Downloading ${downloadUrl}...`);
    const downloadPath = await tc.downloadTool(downloadUrl);
    core.debug(`Downloaded to ${downloadPath}`);
    core.info('Extracting Mage...');
    let extPath;
    if (osPlat == 'win32') {
        extPath = await tc.extractZip(downloadPath, mageHome);
    }
    else {
        extPath = await tc.extractTar(downloadPath, mageHome);
    }
    core.debug(`Extracted to ${extPath}`);
    const cachePath = await tc.cacheDir(extPath, 'mage-action', semver);
    core.debug(`Cached to ${cachePath}`);
    if (cacheBinary && cache.isFeatureAvailable()) {
        core.debug(`Caching to GitHub actions cache`);
        await cache.saveCache([getExePath(mageHome)], getCacheKey(semver));
    }
    return getExePath(cachePath);
}
const getCacheKey = (semver) => {
    return util.format('mage-action-cache-%s', semver);
};
const getExePath = (basePath) => {
    const exePath = path.join(basePath, osPlat == 'win32' ? 'mage.exe' : 'mage');
    core.debug(`Exe path is ${exePath}`);
    return exePath;
};
const getFilename = (semver) => {
    const platform = osPlat == 'win32' ? 'Windows' : osPlat == 'darwin' ? 'macOS' : 'Linux';
    const arch = osArch == 'x64' ? '64bit' : osArch == 'arm64' ? 'ARM64' : '32bit';
    const ext = osPlat == 'win32' ? 'zip' : 'tar.gz';
    return util.format('mage_%s_%s-%s.%s', semver, platform, arch, ext);
};
